import assert from 'assert'
import App, { state, sequences, props } from 'cerebral'
import { Container, connect } from './'
import { render, fireEvent } from '@testing-library/vue'

// Get Vue from global scope
const Vue = global.Vue
const nextTick = Vue.nextTick

describe('Vuejs', () => {
  // Test state variables
  let sequenceIsFn = false
  let barValue = null
  let sequenceIsFunction = false
  let unmounted = false

  // Reset test variables after each test
  afterEach(() => {
    sequenceIsFn = false
    barValue = null
    sequenceIsFunction = false
    unmounted = false
  })

  describe('Container', () => {
    it('should be able to expose app', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        {
          template: `<div data-testid="foo-display">{{foo}}</div>`,
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('foo-display').textContent, 'bar')
    })

    it('should throw when no app provided', () => {
      assert.throws(
        () => Container(),
        (err) =>
          err.message ===
          'Cerebral - You are not passing controller to Container'
      )
    })
  })

  describe('connect', () => {
    it('should be able to register component into dependencyStore before vm mounting', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })

      let isMounted = false
      let beforeMountCalled = false

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        {
          name: 'Test',
          template: `<div data-testid="foo-display">{{foo}}</div>`,
          beforeMount() {
            beforeMountCalled = true
          },
          mounted() {
            isMounted = true
            const components = app.dependencyStore.getAllUniqueEntities()
            assert.strictEqual(components.length, 1)
            assert.strictEqual(components[0]._displayName, 'Test')
          },
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('foo-display').textContent, 'bar')
      assert.strictEqual(beforeMountCalled, true)
      assert.strictEqual(isMounted, true)
    })

    it('should be able to extract sequences', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
        sequences: {
          someSequence: [],
        },
      })

      const TestComponent = connect(
        {
          foo: state`foo`,
          sequence: sequences`someSequence`,
        },
        {
          template: `<div data-testid="foo-display">{{foo}}</div>`,
          mounted() {
            sequenceIsFn = typeof this.sequence === 'function'
          },
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('foo-display').textContent, 'bar')
      assert.strictEqual(sequenceIsFn, true)
    })

    it('should rerender on state update', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
        sequences: {
          methodCalled: [({ store }) => store.set('foo', 'bar2')],
        },
      })

      const TestComponent = connect(
        {
          foo: state`foo`,
          methodCalled: sequences`methodCalled`,
        },
        {
          template: `
            <div>
              <div data-testid="content">{{foo}}</div>
              <button data-testid="update-button" @click="callSequence">Update</button>
            </div>
          `,
          methods: {
            callSequence() {
              this.methodCalled()
            },
          },
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('content').textContent, 'bar')

      await fireEvent.click(getByTestId('update-button'))
      await nextTick()

      assert.strictEqual(app.getState('foo'), 'bar2')
      assert.strictEqual(getByTestId('content').textContent, 'bar2')
    })

    it('should be able to work with vue props', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        {
          props: ['message'],
          template: `<div data-testid="foo-display">{{message}} {{foo}}</div>`,
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component message="hello" /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('foo-display').textContent, 'hello bar')
    })

    it('should be able to work with props tag and computed', async () => {
      const app = App({
        state: {
          foo: {
            baz: 'mip',
          },
          aComputed: (get) => get(props`foo`),
        },
      })

      const TestComponent = connect(
        {
          a: state`aComputed`,
          b: props`bar.id`,
          c: state`foo.${props`propKey`}`,
        },
        {
          props: ['foo', 'bar', 'propKey'],
          template: `<div data-testid="foo-display">{{a}}{{b}}{{c}}</div>`,
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component foo="bar" :bar="{ id: '1' }" propKey="baz" /></container>`,
      })

      await nextTick()
      assert.strictEqual(getByTestId('foo-display').textContent, 'bar1mip')
    })

    it('should be able to watch vue props', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })

      const TestComponentChild = connect(
        {
          foo: state`foo`,
        },
        {
          props: ['message'],
          template: `<div data-testid="child-message">{{message}}</div>`,
        }
      )

      const TestComponent = {
        components: {
          TestComponentChild,
        },
        data() {
          return { message: 'hello' }
        },
        template: `
          <div>
            <test-component-child :message="message" />
            <button data-testid="update-button" @click="updateMessage">Update</button>
          </div>
        `,
        methods: {
          updateMessage() {
            this.message = 'updated'
          },
        },
      }

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component /></container>`,
      })

      await nextTick()
      await nextTick()
      assert.strictEqual(getByTestId('child-message').textContent, 'hello')

      await fireEvent.click(getByTestId('update-button'))
      await nextTick()

      assert.strictEqual(getByTestId('child-message').textContent, 'updated')
    })

    it('should be able to work with external context and sequences', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
        sequences: {
          someSequence: [],
        },
      })

      const TestComponent = connect(
        {
          foo: state`foo`,
          sequence: sequences`someSequence`,
        },
        {
          props: ['externalValue'],
          template: `<div data-testid="foo-display">{{foo}} {{externalValue}}</div>`,
          mounted() {
            barValue = this.externalValue
            sequenceIsFunction = typeof this.sequence === 'function'
          },
        }
      )

      const { getByTestId } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `<container><my-component external-value="baz" /></container>`,
      })

      await nextTick()

      assert.strictEqual(getByTestId('foo-display').textContent, 'bar baz')
      assert.strictEqual(barValue, 'baz')
      assert.strictEqual(sequenceIsFunction, true)
    })

    it('should be able to unregister component from dependencyStore before destroying vm', async () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })

      // Set lifecycle hook based on Vue version
      const isVue3 = Vue && Vue.version && Vue.version.startsWith('3')
      const destroyHookName = isVue3 ? 'unmounted' : 'destroyed'

      const componentOptions = {
        template: `<div data-testid="foo-display">{{foo}}</div>`,
      }

      componentOptions[destroyHookName] = function () {
        unmounted = true
        assert.deepStrictEqual(app.dependencyStore.getAllUniqueEntities(), [])
      }

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        componentOptions
      )

      const { getByTestId, unmount } = render({
        components: {
          container: Container(app),
          'my-component': TestComponent,
        },
        template: `
          <container>
            <my-component />
          </container>
        `,
      })

      await nextTick()

      assert.strictEqual(getByTestId('foo-display').textContent, 'bar')

      unmount()
      await nextTick()

      assert.strictEqual(unmounted, true)
      assert.deepStrictEqual(app.dependencyStore.getAllUniqueEntities(), [])
    })
  })
})
